"use client";

import React from 'react';
import { motion } from 'framer-motion';
import { useTranslations } from 'next-intl';
import { Briefcase, Award, Lightbulb, Users } from 'lucide-react';
import { SectionHeader } from '../ui/SectionHeader';
import { NeoCard } from '../ui/NeoCard';
import { NeoTag } from '../ui/NeoTag';

type EventType = 'milestone' | 'award' | 'project' | 'collaboration';

interface TimelineEventConfig {
  key: string;
  year: string;
  type: EventType;
}

const eventsConfig: TimelineEventConfig[] = [
  { key: 'terra', year: '2025', type: 'project' },
  { key: 'metalcore', year: '2024', type: 'project' },
  { key: 'queens', year: '2023', type: 'milestone' },
  { key: 'bassMusic', year: '2022', type: 'project' },
  { key: 'sync', year: '2021', type: 'award' },
  { key: 'prolific', year: '2020', type: 'milestone' },
  { key: 'synthwave', year: '2019', type: 'project' },
  { key: 'metal', year: '2011-2013', type: 'collaboration' },
];

const typeConfig = {
  milestone: {
    bgClass: 'bg-neo-accent',
    borderClass: 'border-neo-accent',
    tagVariant: 'inverted' as const,
    icon: Lightbulb,
  },
  award: {
    bgClass: 'bg-neo-accent',
    borderClass: 'border-neo-accent',
    tagVariant: 'accent' as const,
    icon: Award,
  },
  project: {
    bgClass: 'bg-neo-accent',
    borderClass: 'border-neo-accent',
    tagVariant: 'default' as const,
    icon: Briefcase,
  },
  collaboration: {
    bgClass: 'bg-neo-text',
    borderClass: 'border-neo-text',
    tagVariant: 'outline' as const,
    icon: Users,
  },
};

const staggerContainer = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.15, delayChildren: 0.2 }
  }
};

const fadeInUp = {
  hidden: { opacity: 0, y: 30 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: [0.25, 0.4, 0.25, 1] as const }
  }
};

export const NeoTimeline = () => {
  const t = useTranslations('about.timeline');

  return (
    <section className="py-24 bg-neo-bg">
      <div className="container mx-auto px-4 md:px-6">
        <SectionHeader
          number="03"
          title={t('title')}
          subtitle={t('subtitle')}
        />

        <motion.div
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          variants={staggerContainer}
          className="relative"
        >
          {/* Vertical Line - Central on desktop, left on mobile */}
          <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-1 bg-neo-border md:-translate-x-1/2" />

          <div className="space-y-12 md:space-y-16">
            {eventsConfig.map((event, index) => {
              const config = typeConfig[event.type];
              const Icon = config.icon;
              const isLeft = index % 2 === 0;

              return (
                <motion.div
                  key={event.key}
                  variants={fadeInUp}
                  className={`relative flex items-start ${
                    isLeft ? 'md:flex-row' : 'md:flex-row-reverse'
                  }`}
                >
                  {/* Spacer for desktop alignment */}
                  <div className="flex-1 hidden md:block" />

                  {/* Square Dot - Neo-brutalist style */}
                  <div className="absolute left-4 md:left-1/2 top-6 transform -translate-x-1/2 z-10">
                    <div className={`w-4 h-4 ${config.bgClass} border-2 border-neo-border`} />
                  </div>

                  {/* Content Card */}
                  <div className={`flex-1 pl-12 md:pl-0 ${isLeft ? 'md:pr-12' : 'md:pl-12'}`}>
                    <NeoCard
                      hover="lift"
                      padding="lg"
                      className="relative group"
                    >
                      {/* Year - Large display - inside card, toward timeline side */}
                      <div className={`absolute top-0 ${
                        isLeft
                          ? 'right-4 md:right-6'
                          : 'left-4 md:left-6'
                      }`}>
                        <span
                          className="text-5xl md:text-6xl font-black tracking-tighter"
                          style={{
                            WebkitTextStroke: '2px var(--neo-border)',
                            color: 'transparent'
                          }}
                        >
                          {event.year}
                        </span>
                      </div>

                      {/* Type Badge - aligned opposite to the year */}
                      <div className={`flex items-center gap-2 mb-4 pt-8 ${
                        isLeft ? '' : 'md:justify-end'
                      }`}>
                        <NeoTag variant={config.tagVariant} size="sm">
                          <Icon className="w-3 h-3 mr-1" />
                          {t(`events.${event.key}.type`)}
                        </NeoTag>
                      </div>

                      {/* Title */}
                      <h3 className={`text-xl md:text-2xl font-black uppercase tracking-tight mb-3 text-neo-text ${
                        !isLeft ? 'md:text-right' : ''
                      }`}>
                        {t(`events.${event.key}.title`)}
                      </h3>

                      {/* Description */}
                      <p className={`font-mono text-sm opacity-70 leading-relaxed ${
                        !isLeft ? 'md:text-right' : ''
                      }`}>
                        {t(`events.${event.key}.description`)}
                      </p>

                      {/* Decorative corner */}
                      <div className={`absolute bottom-0 ${isLeft ? 'right-0' : 'left-0'} w-8 h-8 ${config.bgClass} opacity-20`} />
                    </NeoCard>
                  </div>
                </motion.div>
              );
            })}
          </div>

          {/* End marker */}
          <div className="absolute left-4 md:left-1/2 -bottom-4 transform -translate-x-1/2">
            <div className="w-6 h-6 bg-neo-accent border-2 border-neo-border rotate-45" />
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default NeoTimeline;

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useTranslations } from "next-intl";
import { motion } from "framer-motion";
import {
  Mail,
  MapPin,
  Music,
  Headphones,
  Mic2,
  Sliders,
  Globe,
  BadgeCheck,
  Users,
  Instagram,
  Linkedin,
  Youtube,
  ExternalLink,
  Award,
  Trophy,
  Guitar,
  Play,
  Star,
  Gamepad2,
  Film,
  Piano,
  ChevronLeft,
  ChevronRight,
  type LucideIcon,
} from "lucide-react";
import Image from "next/image";
import { BrutalistButton } from "../ui/BrutalistButton";
import { ImageModal } from "../ui/ImageModal";
import { SectionHeader } from "../ui/SectionHeader";
import { NeoNavbar } from "../NeoNavbar";
import { NeoFooter } from "../NeoFooter";
import { NeoCard } from "../ui/NeoCard";
import { NeoTag } from "../ui/NeoTag";
import { Link } from "@/i18n/routing";

const staggerContainer = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.15, delayChildren: 0.1 },
  },
};

const fadeInUp = {
  hidden: { opacity: 0, y: 40 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.7,
      ease: [0.25, 0.4, 0.25, 1] as const,
    },
  },
};

const photoReveal = {
  hidden: {
    opacity: 0,
    scale: 0.95,
    y: 20,
  },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: {
      duration: 0.8,
      ease: [0.25, 0.4, 0.25, 1] as const,
      delay: 0.2,
    },
  },
};

// Testimonials Carousel Component
interface Testimonial {
  id: number;
  name: string;
  role: string;
  avatar: string;
  text: string;
  date: string;
}

const TestimonialCard = ({ testimonial }: { testimonial: Testimonial }) => (
  <div className="bg-neo-bg border-2 border-neo-border p-6 md:p-8 h-full transition-all duration-300 hover:-translate-y-1 hover:shadow-[6px_6px_0px_0px_var(--neo-accent)]">
    {/* Quote & Stars */}
    <div className="flex items-start justify-between mb-4">
      <div className="text-5xl md:text-6xl font-serif text-neo-accent/30 leading-none -mt-2">
        &ldquo;
      </div>
      <div className="flex gap-0.5">
        {[...Array(5)].map((_, starIdx) => (
          <Star key={starIdx} className="w-4 h-4 fill-neo-accent text-neo-accent" />
        ))}
      </div>
    </div>

    {/* Text */}
    <p className="text-sm md:text-base text-neo-text/80 mb-6 italic leading-relaxed line-clamp-4">
      {testimonial.text}
    </p>

    {/* Author */}
    <div className="flex items-center gap-3 pt-4 border-t-2 border-neo-border">
      <div className="relative w-12 h-12 rounded-full overflow-hidden border-2 border-neo-accent flex-shrink-0">
        <Image src={testimonial.avatar} alt={testimonial.name} fill className="object-cover" />
      </div>
      <div className="min-w-0">
        <h4 className="font-bold text-neo-text truncate">{testimonial.name}</h4>
        <p className="font-mono text-xs text-neo-text/60 truncate">{testimonial.role}</p>
        <p className="font-mono text-xs text-neo-accent">{testimonial.date}</p>
      </div>
    </div>
  </div>
);

const TestimonialsCarousel = ({
  testimonials,
  locale,
}: {
  testimonials: Testimonial[];
  locale: string;
}) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  // Duplicate array for infinite loop effect
  const extendedTestimonials = [...testimonials, ...testimonials, ...testimonials];
  const offset = testimonials.length; // Start from middle set

  const nextSlide = useCallback(() => {
    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
  }, [testimonials.length]);

  const prevSlide = useCallback(() => {
    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
  }, [testimonials.length]);

  // Auto-scroll lent (6 secondes)
  useEffect(() => {
    if (isPaused) return;
    const interval = setInterval(nextSlide, 6000);
    return () => clearInterval(interval);
  }, [isPaused, nextSlide]);

  // Calculate the translateX percentage
  // Each card is ~33.33% width on desktop with gap
  const getTranslateX = () => {
    // We show 3 cards at a time, so each step moves by 1 card width (~33.33%)
    return `calc(-${(currentIndex + offset) * 33.333}% - ${(currentIndex + offset) * 8}px)`;
  };

  return (
    <section
      className="py-24 bg-neo-surface overflow-hidden"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="container mx-auto px-4 md:px-6">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-end md:justify-between mb-12">
          <div>
            <div className="font-mono font-bold text-neo-accent mb-4 flex items-center gap-2">
              <span className="bg-neo-text text-neo-accent px-2 py-1">05</span>
              <span className="text-neo-text/60">
                // {locale === "fr" ? "AVIS CLIENTS" : "CLIENT REVIEWS"}
              </span>
            </div>
            <h2 className="text-4xl md:text-5xl font-black uppercase tracking-tight text-neo-text">
              {locale === "fr" ? "Témoignages" : "Testimonials"}
            </h2>
            <p className="font-mono text-sm text-neo-text/60 mt-2 max-w-md">
              {locale === "fr"
                ? "Retours de mes collaborateurs sur SoundBetter"
                : "Feedback from my collaborators on SoundBetter"}
            </p>
          </div>

          {/* Navigation Arrows */}
          <div className="flex items-center gap-3 mt-6 md:mt-0">
            <button
              onClick={prevSlide}
              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
              aria-label="Previous"
            >
              <ChevronLeft className="w-6 h-6" />
            </button>
            <button
              onClick={nextSlide}
              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
              aria-label="Next"
            >
              <ChevronRight className="w-6 h-6" />
            </button>
          </div>
        </div>

        {/* Carousel - Sliding container */}
        <div className="relative overflow-hidden py-2 -my-2">
          <motion.div
            className="flex gap-6 pt-2"
            animate={{ x: getTranslateX() }}
            transition={{ duration: 0.6, ease: [0.25, 0.4, 0.25, 1] }}
          >
            {extendedTestimonials.map((testimonial, index) => (
              <div
                key={`${testimonial.id}-${index}`}
                className="w-full md:w-[calc(50%-12px)] lg:w-[calc(33.333%-16px)] flex-shrink-0"
              >
                <TestimonialCard testimonial={testimonial} />
              </div>
            ))}
          </motion.div>
        </div>

        {/* Progress Dots */}
        <div className="flex justify-center gap-3 mt-8">
          {testimonials.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentIndex(index)}
              className={`h-3 border-2 border-neo-border transition-all duration-300 ${
                index === currentIndex ? "w-10 bg-neo-accent" : "w-3 bg-neo-bg hover:bg-neo-text/20"
              }`}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>

        {/* CTA SoundBetter - Orange accent button */}
        <div className="text-center mt-12">
          <a
            href="https://soundbetter.com/profiles/402365-lo%C3%AFc-ghanem--voyager1"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-3 bg-neo-accent text-neo-text-inverse px-8 py-4 font-bold uppercase tracking-wide border-2 border-neo-border hover:bg-neo-text hover:text-neo-accent transition-colors shadow-[4px_4px_0px_0px_var(--neo-text)] hover:shadow-none hover:translate-x-1 hover:translate-y-1"
          >
            <Star className="w-5 h-5" />
            {locale === "fr"
              ? "Voir tous les avis sur SoundBetter"
              : "View All Reviews on SoundBetter"}
            <ExternalLink className="w-5 h-5" />
          </a>
        </div>
      </div>
    </section>
  );
};

export const NeoAbout = ({ locale }: { locale: string }) => {
  const t = useTranslations("about");
  const [imageModal, setImageModal] = useState<{ src: string; title: string } | null>(null);

  const skills = [
    {
      title: t("skills.composition.title"),
      icon: Music,
      items: t.raw("skills.composition.items") as string[],
    },
    {
      title: t("skills.production.title"),
      icon: Headphones,
      items: t.raw("skills.production.items") as string[],
    },
    {
      title: t("skills.artistProduction.title"),
      icon: Users,
      items: t.raw("skills.artistProduction.items") as string[],
    },
    {
      title: t("skills.vocalProduction.title"),
      icon: Mic2,
      items: t.raw("skills.vocalProduction.items") as string[],
    },
    {
      title: t("skills.postProduction.title"),
      icon: Sliders,
      items: t.raw("skills.postProduction.items") as string[],
    },
  ];

  const stats = [
    { val: "24", label: t("achievements.albums") },
    { val: "8", label: t("achievements.labels") },
    { val: "4", label: t("achievements.publishers") },
    { val: "14", label: t("achievements.years") },
  ];

  type LocalizedText = { fr: string; en: string };
  const localeKey: keyof LocalizedText = locale === "fr" ? "fr" : "en";

  const labelPartners: Array<{
    name: string;
    logo: string;
    description?: LocalizedText;
